values
($$PACF-M01-O1$$, 'pacf-item-bank-1.1.0', $$M01$$, $$M$$, 1, $$objective$$, $${"stem":"下面哪一项最准确地描述了“大语言模型”和“聊天产品”的关系？","options":[{"id":"A","text":"二者完全相同，只是叫法不同"},{"id":"B","text":"聊天产品通常把模型、界面、账户、工具和安全策略组合在一起"},{"id":"C","text":"大语言模型是聊天产品中的长期记忆数据库"},{"id":"D","text":"聊天产品一定只使用一个固定模型"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":3},{"id":"C","score":0},{"id":"D","score":0}]}$$::jsonb, $$产品通常是模型及其外围能力的封装，不能把产品名直接等同于模型。$$, array[$$S17$$, $$S18$$, $$P03$$]::text[], true, 'active'),
($$PACF-M01-S1$$, 'pacf-item-bank-1.1.0', $$M01$$, $$M$$, 2, $$scenario$$, $${"stem":"团队说要“做一个 Agent 自动整理客户反馈”。你首先应该做什么？","options":[{"id":"A","text":"直接选择一个多 Agent 平台"},{"id":"B","text":"先写一个人格提示词让它扮演客服"},{"id":"C","text":"先确认任务是否只需固定步骤的 Workflow"},{"id":"D","text":"画出模型、数据、工具、状态、权限和人工接管，再选择最小架构"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":1},{"id":"C","score":2},{"id":"D","score":3}]}$$::jsonb, $$高级表现是先理解构件和任务，再决定是否需要 Agent。$$, array[$$S17$$, $$S18$$, $$P01$$, $$P10$$]::text[], true, 'active'),
($$PACF-M01-C1$$, 'pacf-item-bank-1.1.0', $$M01$$, $$M$$, 3, $$constructed$$, $${"stem":"用不超过 180 字，向完全不懂技术的人解释：模型、AI 产品、工具调用、工作流和 Agent 有什么不同。","rubric":[{"id":"M01-1","description":"五个概念均有清楚定义","maxPoints":1},{"id":"M01-2","description":"指出构件之间的组合关系","maxPoints":1},{"id":"M01-3","description":"至少给出一个同任务对比例子","maxPoints":1},{"id":"M01-4","description":"没有把 Agent 等同于聊天机器人或自动化脚本","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"M01-1","description":"五个概念均有清楚定义","maxPoints":1},{"id":"M01-2","description":"指出构件之间的组合关系","maxPoints":1},{"id":"M01-3","description":"至少给出一个同任务对比例子","maxPoints":1},{"id":"M01-4","description":"没有把 Agent 等同于聊天机器人或自动化脚本","maxPoints":1}]}$$::jsonb, $$检验是否形成可迁移的系统构件心智模型。$$, array[$$S17$$, $$S18$$, $$P01$$]::text[], false, 'active'),
($$PACF-M01-P1$$, 'pacf-item-bank-1.1.0', $$M01$$, $$M$$, 4, $$practical$$, $${"stem":"为“每周收集用户反馈并生成待办”画出三种方案：人工+聊天、固定 Workflow、Agent。标出模型、工具、数据、状态和人工节点。","rubric":[{"id":"M01-1","description":"三种方案的构件标注完整","maxPoints":1},{"id":"M01-2","description":"能说明固定路径与动态决策差别","maxPoints":1},{"id":"M01-3","description":"给出各自适用条件","maxPoints":1},{"id":"M01-4","description":"最终选择有成本与风险依据","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"M01-1","description":"三种方案的构件标注完整","maxPoints":1},{"id":"M01-2","description":"能说明固定路径与动态决策差别","maxPoints":1},{"id":"M01-3","description":"给出各自适用条件","maxPoints":1},{"id":"M01-4","description":"最终选择有成本与风险依据","maxPoints":1}]}$$::jsonb, $$要求把术语转化为真实架构判断。$$, array[$$S17$$, $$S18$$, $$S20$$]::text[], false, 'active'),
($$PACF-M02-O1$$, 'pacf-item-bank-1.1.0', $$M02$$, $$M$$, 1, $$objective$$, $${"stem":"为什么模型给出的论文标题和链接看起来很真实，仍然需要核验？","options":[{"id":"A","text":"链接只在手机上才会失效"},{"id":"B","text":"只有免费模型才会编造"},{"id":"C","text":"只要要求“不要编造”就不需要核验"},{"id":"D","text":"模型可能按语言模式生成并不存在的细节"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":0},{"id":"C","score":0},{"id":"D","score":3}]}$$::jsonb, $$生成式模型以概率方式生成内容，流畅度不等于事实真实性。$$, array[$$S15$$, $$P04$$, $$P05$$]::text[], true, 'active'),
($$PACF-M02-S1$$, 'pacf-item-bank-1.1.0', $$M02$$, $$M$$, 2, $$scenario$$, $${"stem":"AI 对同一道业务题前后给出两个不同数字，你最合适的处理方式是？","options":[{"id":"A","text":"多问几遍，用出现次数最多的答案"},{"id":"B","text":"把温度调低后直接采用"},{"id":"C","text":"检查数据来源、计算过程和口径，必要时用确定性工具复算"},{"id":"D","text":"选语气更肯定的一个"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":2},{"id":"C","score":3},{"id":"D","score":0}]}$$::jsonb, $$波动提示需要证据与确定性验证，不能用多数投票替代事实。$$, array[$$S12$$, $$S14$$, $$P05$$]::text[], true, 'active'),
($$PACF-M02-C1$$, 'pacf-item-bank-1.1.0', $$M02$$, $$M$$, 3, $$constructed$$, $${"stem":"解释“提示词可以降低部分错误概率，但不能保证没有幻觉”，并给出两个不同风险等级的例子。","rubric":[{"id":"M02-1","description":"解释概率生成或知识边界","maxPoints":1},{"id":"M02-2","description":"区分低风险和高风险任务","maxPoints":1},{"id":"M02-3","description":"给出提示之外的核验措施","maxPoints":1},{"id":"M02-4","description":"说明何时应拒用或转向专业人士","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"M02-1","description":"解释概率生成或知识边界","maxPoints":1},{"id":"M02-2","description":"区分低风险和高风险任务","maxPoints":1},{"id":"M02-3","description":"给出提示之外的核验措施","maxPoints":1},{"id":"M02-4","description":"说明何时应拒用或转向专业人士","maxPoints":1}]}$$::jsonb, $$防止把可靠性简化为提示词技巧。$$, array[$$S14$$, $$S15$$, $$P04$$]::text[], false, 'active'),
($$PACF-M02-P1$$, 'pacf-item-bank-1.1.0', $$M02$$, $$M$$, 4, $$practical$$, $${"stem":"用同一事实型问题分别测试两种模型三次，记录差异，并设计一套不依赖“多问几遍”的核验流程。","rubric":[{"id":"M02-1","description":"完整记录六次输出差异","maxPoints":1},{"id":"M02-2","description":"定位关键可核验主张","maxPoints":1},{"id":"M02-3","description":"使用原始来源或确定性工具","maxPoints":1},{"id":"M02-4","description":"总结模型适用边界而非只评输赢","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"M02-1","description":"完整记录六次输出差异","maxPoints":1},{"id":"M02-2","description":"定位关键可核验主张","maxPoints":1},{"id":"M02-3","description":"使用原始来源或确定性工具","maxPoints":1},{"id":"M02-4","description":"总结模型适用边界而非只评输赢","maxPoints":1}]}$$::jsonb, $$通过实验理解不确定性与核验。$$, array[$$S12$$, $$S14$$]::text[], false, 'active'),
($$PACF-M03-O1$$, 'pacf-item-bank-1.1.0', $$M03$$, $$M$$, 1, $$objective$$, $${"stem":"下面哪项最准确地区分“当前上下文”和“长期记忆”？","options":[{"id":"A","text":"二者都等于模型训练数据"},{"id":"B","text":"只要上传文件，模型就永久记住全文"},{"id":"C","text":"上下文是当前任务可用的信息，长期记忆是跨会话保存并可再次取用的信息"},{"id":"D","text":"上下文永久保存，长期记忆只在一次回答中有效"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":0},{"id":"C","score":3},{"id":"D","score":0}]}$$::jsonb, $$上下文、长期记忆、训练知识和文件检索是不同机制。$$, array[$$M03$$, $$P06$$]::text[], true, 'active'),
($$PACF-M03-S1$$, 'pacf-item-bank-1.1.0', $$M03$$, $$M$$, 2, $$scenario$$, $${"stem":"一个长对话已经混入多版需求，AI 开始反复遗漏。最佳下一步是？","options":[{"id":"A","text":"让 AI 猜测哪一版有效"},{"id":"B","text":"整理当前目标、已确认决定、材料版本和待办，开启干净会话继续"},{"id":"C","text":"继续补一句“请认真阅读上文”"},{"id":"D","text":"重复发送最近一条要求"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":2},{"id":"B","score":3},{"id":"C","score":0},{"id":"D","score":1}]}$$::jsonb, $$状态摘要和干净交接比无限追加上下文更可靠。$$, array[$$P06$$, $$F04$$]::text[], true, 'active'),
($$PACF-M03-C1$$, 'pacf-item-bank-1.1.0', $$M03$$, $$M$$, 3, $$constructed$$, $${"stem":"比较模型训练知识、联网搜索、RAG、会话上下文和长期记忆。分别说明它们可能过时或出错的地方。","rubric":[{"id":"M03-1","description":"五类信息来源均被区分","maxPoints":1},{"id":"M03-2","description":"指出时效性差异","maxPoints":1},{"id":"M03-3","description":"指出检索与生成仍可能出错","maxPoints":1},{"id":"M03-4","description":"说明用户如何确认当前依据","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"M03-1","description":"五类信息来源均被区分","maxPoints":1},{"id":"M03-2","description":"指出时效性差异","maxPoints":1},{"id":"M03-3","description":"指出检索与生成仍可能出错","maxPoints":1},{"id":"M03-4","description":"说明用户如何确认当前依据","maxPoints":1}]}$$::jsonb, $$检验知识边界与状态意识。$$, array[$$S06$$, $$M03$$]::text[], false, 'active'),
($$PACF-M03-P1$$, 'pacf-item-bank-1.1.0', $$M03$$, $$M$$, 4, $$practical$$, $${"stem":"把一个至少三阶段的长任务拆成可跨会话恢复的状态包，并让另一会话仅凭状态包继续执行。","rubric":[{"id":"M03-1","description":"状态包含目标、材料、决定与待办","maxPoints":1},{"id":"M03-2","description":"清楚标注版本和未决问题","maxPoints":1},{"id":"M03-3","description":"新会话能正确恢复","maxPoints":1},{"id":"M03-4","description":"记录并修复一次上下文丢失","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"M03-1","description":"状态包含目标、材料、决定与待办","maxPoints":1},{"id":"M03-2","description":"清楚标注版本和未决问题","maxPoints":1},{"id":"M03-3","description":"新会话能正确恢复","maxPoints":1},{"id":"M03-4","description":"记录并修复一次上下文丢失","maxPoints":1}]}$$::jsonb, $$以恢复能力证明上下文管理，而非依赖产品记忆。$$, array[$$P06$$, $$CORE-11$$]::text[], false, 'active'),
($$PACF-M04-O1$$, 'pacf-item-bank-1.1.0', $$M04$$, $$M$$, 2, $$objective$$, $${"stem":"选择 AI 工具时，下面哪组因素最完整？","options":[{"id":"A","text":"朋友使用数量和广告折扣"},{"id":"B","text":"是否热门、界面是否漂亮"},{"id":"C","text":"模型排行榜和参数量"},{"id":"D","text":"质量、时效、隐私、成本、工具能力和集成条件"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":0},{"id":"C","score":0},{"id":"D","score":3}]}$$::jsonb, $$工具选择必须与任务和约束匹配。$$, array[$$S20$$, $$P09$$]::text[], true, 'active'),
($$PACF-M04-S1$$, 'pacf-item-bank-1.1.0', $$M04$$, $$M$$, 3, $$scenario$$, $${"stem":"每月只处理 20 份格式固定的表格，人工核对很快。有人建议搭多 Agent 系统。最佳决策是？","options":[{"id":"A","text":"只要能节省一分钟就全自动化"},{"id":"B","text":"因为 Agent 更先进，立即搭建"},{"id":"C","text":"先购买最贵模型保证效果"},{"id":"D","text":"先比较模板/脚本/单次模型方案的成本和错误率"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":0},{"id":"C","score":1},{"id":"D","score":2}]}$$::jsonb, $$低频固定任务可能用简单方案更可靠。$$, array[$$S18$$, $$S20$$, $$P15$$]::text[], true, 'active'),
($$PACF-M04-C1$$, 'pacf-item-bank-1.1.0', $$M04$$, $$M$$, 3, $$constructed$$, $${"stem":"为“公开资料行业简报”和“含客户隐私的内部分析”分别提出工具选择，并说明质量、隐私、成本和可追溯性权衡。","rubric":[{"id":"M04-1","description":"两个场景选择不同且合理","maxPoints":1},{"id":"M04-2","description":"覆盖质量和时效","maxPoints":1},{"id":"M04-3","description":"覆盖隐私与权限","maxPoints":1},{"id":"M04-4","description":"覆盖成本和证据追溯","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"M04-1","description":"两个场景选择不同且合理","maxPoints":1},{"id":"M04-2","description":"覆盖质量和时效","maxPoints":1},{"id":"M04-3","description":"覆盖隐私与权限","maxPoints":1},{"id":"M04-4","description":"覆盖成本和证据追溯","maxPoints":1}]}$$::jsonb, $$观察能否按场景做多目标权衡。$$, array[$$S07$$, $$S20$$]::text[], false, 'active'),
($$PACF-M04-P1$$, 'pacf-item-bank-1.1.0', $$M04$$, $$M$$, 4, $$practical$$, $${"stem":"选择一个真实任务，对比人工、单次模型、固定 Workflow 和 Agent 四种方案，形成带测量数据的选型报告。","rubric":[{"id":"M04-1","description":"建立统一质量基线","maxPoints":1},{"id":"M04-2","description":"测量时间与成本","maxPoints":1},{"id":"M04-3","description":"识别风险和失控半径","maxPoints":1},{"id":"M04-4","description":"选择最小可靠方案并说明放弃项","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"M04-1","description":"建立统一质量基线","maxPoints":1},{"id":"M04-2","description":"测量时间与成本","maxPoints":1},{"id":"M04-3","description":"识别风险和失控半径","maxPoints":1},{"id":"M04-4","description":"选择最小可靠方案并说明放弃项","maxPoints":1}]}$$::jsonb, $$高阶选型必须有实测而不是趋势判断。$$, array[$$S18$$, $$S20$$]::text[], false, 'active'),
($$PACF-M05-O1$$, 'pacf-item-bank-1.1.0', $$M05$$, $$M$$, 1, $$objective$$, $${"stem":"AI 生成的内容造成业务错误时，下面哪项最准确？","options":[{"id":"A","text":"模型承担全部责任"},{"id":"B","text":"只要披露用了 AI，人就没有责任"},{"id":"C","text":"最终采用和发布的人或组织仍需承担相应责任"},{"id":"D","text":"使用付费模型即可转移责任"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":0},{"id":"C","score":3},{"id":"D","score":0}]}$$::jsonb, $$AI 辅助不会自动转移人的判断和责任。$$, array[$$S20$$, $$S22$$]::text[], true, 'active'),
