($$PACF-S01-C1$$, 'pacf-item-bank-1.1.0', $$S01$$, $$S$$, 3, $$constructed$$, $${"stem":"从你的日常工作中选择三个候选流程，按频率、价值、标准化、风险和数据准备度排序。","rubric":[{"id":"S01-1","description":"候选来自真实观察","maxPoints":1},{"id":"S01-2","description":"五个维度有证据","maxPoints":1},{"id":"S01-3","description":"排序有明确取舍","maxPoints":1},{"id":"S01-4","description":"至少淘汰一个不适合用例","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S01-1","description":"候选来自真实观察","maxPoints":1},{"id":"S01-2","description":"五个维度有证据","maxPoints":1},{"id":"S01-3","description":"排序有明确取舍","maxPoints":1},{"id":"S01-4","description":"至少淘汰一个不适合用例","maxPoints":1}]}$$::jsonb, $$能拒绝不合适用例是高级表现。$$, array[$$S20$$, $$ORG-01$$]::text[], false, 'active'),
