($$PACF-S02-O1$$, 'pacf-item-bank-1.1.0', $$S02$$, $$S$$, 2, $$objective$$, $${"stem":"可靠 Workflow 除了正常步骤，还必须明确什么？","options":[{"id":"A","text":"异常、重试、状态、人工交接和重复执行处理"},{"id":"B","text":"模型人格名称"},{"id":"C","text":"输出字数越多越好"},{"id":"D","text":"界面颜色"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":0},{"id":"C","score":0},{"id":"D","score":0}]}$$::jsonb, $$可靠流程要处理非理想路径。$$, array[$$S18$$, $$SYS-02$$]::text[], true, 'active'),
($$PACF-S02-S1$$, 'pacf-item-bank-1.1.0', $$S02$$, $$S$$, 3, $$scenario$$, $${"stem":"支付回调可能重复到达，工作流怎样避免重复发放权益？","options":[{"id":"A","text":"每次都重新生成权益"},{"id":"B","text":"用更聪明模型判断"},{"id":"C","text":"使用唯一订单与幂等处理，锁定状态并让重复回调返回同一结果"},{"id":"D","text":"相信支付平台不会重复"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":2},{"id":"C","score":3},{"id":"D","score":0}]}$$::jsonb, $$幂等和状态锁定是关键工作流能力。$$, array[$$SYS-02$$, $$S02$$]::text[], true, 'active'),
($$PACF-S02-C1$$, 'pacf-item-bank-1.1.0', $$S02$$, $$S$$, 3, $$constructed$$, $${"stem":"为“收集反馈→分类→生成任务→人工确认→发布”定义输入输出、状态、分支、重试和交接。","rubric":[{"id":"S02-1","description":"步骤与输入输出完整","maxPoints":1},{"id":"S02-2","description":"状态转换清楚","maxPoints":1},{"id":"S02-3","description":"异常/重试有上限","maxPoints":1},{"id":"S02-4","description":"人工确认和回退明确","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S02-1","description":"步骤与输入输出完整","maxPoints":1},{"id":"S02-2","description":"状态转换清楚","maxPoints":1},{"id":"S02-3","description":"异常/重试有上限","maxPoints":1},{"id":"S02-4","description":"人工确认和回退明确","maxPoints":1}]}$$::jsonb, $$从聊天步骤升级为可运行流程。$$, array[$$SYS-02$$, $$CORE-15$$]::text[], false, 'active'),
($$PACF-S02-P1$$, 'pacf-item-bank-1.1.0', $$S02$$, $$S$$, 4, $$practical$$, $${"stem":"实现或模拟一个至少五步的 Workflow，注入缺失输入、超时和重复请求三类故障。","rubric":[{"id":"S02-1","description":"正常路径可运行","maxPoints":1},{"id":"S02-2","description":"三类故障被检测","maxPoints":1},{"id":"S02-3","description":"重试/回退/人工接管有效","maxPoints":1},{"id":"S02-4","description":"状态和日志足以复盘","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S02-1","description":"正常路径可运行","maxPoints":1},{"id":"S02-2","description":"三类故障被检测","maxPoints":1},{"id":"S02-3","description":"重试/回退/人工接管有效","maxPoints":1},{"id":"S02-4","description":"状态和日志足以复盘","maxPoints":1}]}$$::jsonb, $$可靠性必须经过失效演习。$$, array[$$SYS-02$$, $$SYS-06$$]::text[], false, 'active'),
($$PACF-S03-O1$$, 'pacf-item-bank-1.1.0', $$S03$$, $$S$$, 2, $$objective$$, $${"stem":"与固定 Workflow 相比，Agent 的关键差别是什么？","options":[{"id":"A","text":"Agent 必须包含多个模型"},{"id":"B","text":"Workflow 不能使用 AI"},{"id":"C","text":"Agent 一定有头像"},{"id":"D","text":"Agent 由模型在目标和权限内动态决定部分步骤与工具"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":0},{"id":"C","score":0},{"id":"D","score":3}]}$$::jsonb, $$Agent 的核心是动态编排和自主性，而非外观或数量。$$, array[$$S17$$, $$S18$$]::text[], true, 'active'),
($$PACF-S03-S1$$, 'pacf-item-bank-1.1.0', $$S03$$, $$S$$, 4, $$scenario$$, $${"stem":"任务规则稳定、分支已知、错误代价高。应优先选择？","options":[{"id":"A","text":"让模型每次重新规划"},{"id":"B","text":"固定 Workflow，并只在必要节点使用模型判断和人工审批"},{"id":"C","text":"多 Agent 自由协商"},{"id":"D","text":"完全自主 Agent"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":2},{"id":"B","score":3},{"id":"C","score":0},{"id":"D","score":1}]}$$::jsonb, $$稳定高风险流程通常应限制自主性。$$, array[$$S18$$, $$S20$$]::text[], true, 'active'),
($$PACF-S03-C1$$, 'pacf-item-bank-1.1.0', $$S03$$, $$S$$, 4, $$constructed$$, $${"stem":"为一个确实需要 Agent 的用例说明：为什么 Workflow 不够、Agent 目标、工具、记忆、权限、停止条件和人工接管。","rubric":[{"id":"S03-1","description":"动态决策需求真实","maxPoints":1},{"id":"S03-2","description":"工具/记忆与任务匹配","maxPoints":1},{"id":"S03-3","description":"权限和停止条件明确","maxPoints":1},{"id":"S03-4","description":"人工接管与责任明确","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S03-1","description":"动态决策需求真实","maxPoints":1},{"id":"S03-2","description":"工具/记忆与任务匹配","maxPoints":1},{"id":"S03-3","description":"权限和停止条件明确","maxPoints":1},{"id":"S03-4","description":"人工接管与责任明确","maxPoints":1}]}$$::jsonb, $$避免为了 Agent 而 Agent。$$, array[$$S17$$, $$S18$$, $$S19$$]::text[], false, 'active'),
($$PACF-S03-P1$$, 'pacf-item-bank-1.1.0', $$S03$$, $$S$$, 4, $$practical$$, $${"stem":"构建一个最小 Agent，在沙箱内完成多步任务，并与固定 Workflow 比较成功率、成本和失控行为。","rubric":[{"id":"S03-1","description":"Agent 循环和工具调用可观察","maxPoints":1},{"id":"S03-2","description":"权限限制有效","maxPoints":1},{"id":"S03-3","description":"与 Workflow 使用同一评测集","maxPoints":1},{"id":"S03-4","description":"结论说明是否值得保留 Agent","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S03-1","description":"Agent 循环和工具调用可观察","maxPoints":1},{"id":"S03-2","description":"权限限制有效","maxPoints":1},{"id":"S03-3","description":"与 Workflow 使用同一评测集","maxPoints":1},{"id":"S03-4","description":"结论说明是否值得保留 Agent","maxPoints":1}]}$$::jsonb, $$Agent 能力包括选择不用 Agent。$$, array[$$SYS-04$$, $$S18$$]::text[], false, 'active'),
($$PACF-S04-O1$$, 'pacf-item-bank-1.1.0', $$S04$$, $$S$$, 3, $$objective$$, $${"stem":"一次 Demo 成功为什么不能证明 AI 系统可靠？","options":[{"id":"A","text":"只要换更贵模型就可靠"},{"id":"B","text":"Demo 时间太短"},{"id":"C","text":"系统可能在不同输入、模型版本和异常条件下失败，需要代表性评测与运行监控"},{"id":"D","text":"必须录制更多视频"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":0},{"id":"C","score":3},{"id":"D","score":0}]}$$::jsonb, $$可靠性需要分布覆盖、回归和运行证据。$$, array[$$S05$$, $$S06$$]::text[], true, 'active'),
($$PACF-S04-S1$$, 'pacf-item-bank-1.1.0', $$S04$$, $$S$$, 4, $$scenario$$, $${"stem":"更换模型后平均质量相近，但高风险案例错误翻倍。应怎么发布？","options":[{"id":"A","text":"阻止发布，分析分层指标并修复后运行回归"},{"id":"B","text":"平均分没变，直接发布"},{"id":"C","text":"只在夜间发布"},{"id":"D","text":"隐藏高风险样本"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":0},{"id":"C","score":1},{"id":"D","score":2}]}$$::jsonb, $$总体平均不能掩盖关键风险退化。$$, array[$$SYS-05$$, $$S05$$]::text[], true, 'active'),
($$PACF-S04-C1$$, 'pacf-item-bank-1.1.0', $$S04$$, $$S$$, 4, $$constructed$$, $${"stem":"为一个客服 Agent 设计离线评测集和在线监控，覆盖质量、安全、成本、延迟和人工接管。","rubric":[{"id":"S04-1","description":"样本覆盖常见/边界/高风险","maxPoints":1},{"id":"S04-2","description":"质量和安全阈值明确","maxPoints":1},{"id":"S04-3","description":"在线指标含成本延迟和接管","maxPoints":1},{"id":"S04-4","description":"定义回归和停止发布规则","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S04-1","description":"样本覆盖常见/边界/高风险","maxPoints":1},{"id":"S04-2","description":"质量和安全阈值明确","maxPoints":1},{"id":"S04-3","description":"在线指标含成本延迟和接管","maxPoints":1},{"id":"S04-4","description":"定义回归和停止发布规则","maxPoints":1}]}$$::jsonb, $$完整评测包含上线前和运行中。$$, array[$$SYS-05$$, $$S06$$]::text[], false, 'active'),
($$PACF-S04-P1$$, 'pacf-item-bank-1.1.0', $$S04$$, $$S$$, 4, $$practical$$, $${"stem":"为一个真实 Workflow/Agent 建立至少 20 个样本的 Eval 包，运行基线与一次改动后的回归并提交日志。","rubric":[{"id":"S04-1","description":"样本具有代表性和风险分层","maxPoints":1},{"id":"S04-2","description":"评分规则可复现","maxPoints":1},{"id":"S04-3","description":"基线与改动结果可比较","maxPoints":1},{"id":"S04-4","description":"日志能定位失败并支持发布决定","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S04-1","description":"样本具有代表性和风险分层","maxPoints":1},{"id":"S04-2","description":"评分规则可复现","maxPoints":1},{"id":"S04-3","description":"基线与改动结果可比较","maxPoints":1},{"id":"S04-4","description":"日志能定位失败并支持发布决定","maxPoints":1}]}$$::jsonb, $$这是专业全测的系统综合实作候选。$$, array[$$SYS-05$$, $$S05$$, $$S06$$]::text[], false, 'active'),
($$PACF-S05-O1$$, 'pacf-item-bank-1.1.0', $$S05$$, $$S$$, 3, $$objective$$, $${"stem":"组织部署 AI 工具后使用率仍很低，最不充分的解释是什么？","options":[{"id":"A","text":"员工不够积极"},{"id":"B","text":"可能存在权限、技能、流程、支持或激励问题，需要诊断"},{"id":"C","text":"工具未嵌入真实工作"},{"id":"D","text":"风险边界不清导致员工不敢用"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":0},{"id":"C","score":0},{"id":"D","score":0}]}$$::jsonb, $$把采用问题归咎个人会忽略系统条件。$$, array[$$S07$$, $$ORG-03$$]::text[], true, 'active'),
($$PACF-S05-S1$$, 'pacf-item-bank-1.1.0', $$S05$$, $$S$$, 5, $$scenario$$, $${"stem":"组织有 20 个 AI 用例提案，但资源只能支持 5 个。最佳做法是？","options":[{"id":"A","text":"全部小规模启动"},{"id":"B","text":"优先领导最喜欢的"},{"id":"C","text":"优先技术最复杂的"},{"id":"D","text":"按价值、风险、准备度、可扩展性和学习价值排序，并设置停止条件"}]}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":1},{"id":"C","score":2},{"id":"D","score":3}]}$$::jsonb, $$组织能力包含组合管理和主动淘汰。$$, array[$$ORG-01$$, $$S05$$]::text[], true, 'active'),
($$PACF-S05-C1$$, 'pacf-item-bank-1.1.0', $$S05$$, $$S$$, 5, $$constructed$$, $${"stem":"设计一个组织 AI 采用方案，包含角色、分层培训、允许/禁止场景、支持渠道、指标和复盘。","rubric":[{"id":"S05-1","description":"角色与责任明确","maxPoints":1},{"id":"S05-2","description":"培训按能力和风险分层","maxPoints":1},{"id":"S05-3","description":"政策与支持可执行","maxPoints":1},{"id":"S05-4","description":"采用/价值/风险指标及复盘完整","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S05-1","description":"角色与责任明确","maxPoints":1},{"id":"S05-2","description":"培训按能力和风险分层","maxPoints":1},{"id":"S05-3","description":"政策与支持可执行","maxPoints":1},{"id":"S05-4","description":"采用/价值/风险指标及复盘完整","maxPoints":1}]}$$::jsonb, $$工具上线不是组织改变的终点。$$, array[$$S07$$, $$ORG-02$$, $$ORG-03$$]::text[], false, 'active'),
($$PACF-S05-P1$$, 'pacf-item-bank-1.1.0', $$S05$$, $$S$$, 5, $$practical$$, $${"stem":"提交一个真实团队的 30/60/90 天 AI 改变案例，包含基线、用例组合、治理、培训、采用和结果证据。","rubric":[{"id":"S05-1","description":"有真实基线和责任人","maxPoints":1},{"id":"S05-2","description":"治理与能力建设同步","maxPoints":1},{"id":"S05-3","description":"采用和业务结果有数据","maxPoints":1},{"id":"S05-4","description":"能停止无效用例并持续改进","maxPoints":1}]}$$::jsonb, $${"rubric":[{"id":"S05-1","description":"有真实基线和责任人","maxPoints":1},{"id":"S05-2","description":"治理与能力建设同步","maxPoints":1},{"id":"S05-3","description":"采用和业务结果有数据","maxPoints":1},{"id":"S05-4","description":"能停止无效用例并持续改进","maxPoints":1}]}$$::jsonb, $$L5 必须由真实组织采用证据支持。$$, array[$$ORG-01$$, $$ORG-05$$, $$S07$$]::text[], false, 'active')
on conflict (id) do update
set
  item_bank_version = excluded.item_bank_version,
  competency_id = excluded.competency_id,
  dimension_code = excluded.dimension_code,
  target_level = excluded.target_level,
  item_type = excluded.item_type,
  prompt_payload = excluded.prompt_payload,
  scoring_payload = excluded.scoring_payload,
  rationale = excluded.rationale,
  source_anchors = excluded.source_anchors,
  quick_eligible = excluded.quick_eligible,
  status = excluded.status,
  updated_at = now();

